using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AzimuthRingOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/AzimuthRing Omen Data")]
public class AzimuthRingOmenData : OmenData
{
	[Header("Azimuth Ring")]
	[SerializeField]
	private ZenithRingOmenData zenithRingOmenData;

	private Func<int, int> omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate(int purifyAmount)
		{
			if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentPlayerHearts == 1)
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
				return purifyAmount + ActionValue;
			}
			return purifyAmount;
		};
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyStartModifierOmenActions.Add(omenAction);
		ReferenceSingleton<PurifyOmensHandler>.Instance.AzimuthRingFeedbackAction = delegate
		{
			if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentPlayerHearts == 1)
			{
				omenInstance.PlayBlinkingFeedback();
			}
			else
			{
				omenInstance.StopBlinkingFeedback();
			}
		};
		ReferenceSingleton<PurifyOmensHandler>.Instance.AzimuthRingFeedbackAction();
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyStartModifierOmenActions.Remove(omenAction);
		ReferenceSingleton<PurifyOmensHandler>.Instance.AzimuthRingFeedbackAction = null;
	}

	public override string OmenConvertedDescription()
	{
		return GetOmenRawLocalizedDescription() + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + zenithRingOmenData.GetDealAdditionalPurifyLocalizedDescription(ActionValue);
	}
}
